// Scripted fixture for local UI and contract tests, never used by live AI.
export function planFixture(spec,id='mystery') {
  const primary=spec.gameplay?.primary || 'reasoning',support=spec.gameplay?.secondary || [];
  const titles=['Inspect the station records','Find the next stop','Combine the travellers notes','Read the station message','Restore the travel document'];
  const descriptions={reasoning:'Compare the printed records and choose the entry matching all stated facts.',sequence:'Use the printed ordering rules to choose the correct route sequence.',code:'Use the printed letter key to decode a short station message.',discussion:'Read the two printed notes in different roles and agree which entry fits both.'};
  return {id,title:id==='mystery'?'The Missing Travel Document':'The Journey Message Team',summary:'A friendly Journey to the West paper adventure. Your team follows station records to restore a missing travel document.',opening:'The journey companions arrive at a quiet station. Their travel document has been mixed up with the station records. Help them use printed evidence to put the journey back on track.',roles:'The journey companions, taking reader, recorder and checker roles.',goal:'Restore the missing travel document using five connected paper checkpoints.',preparation:'Print the Player Pack. Keep the Host or Teacher Guide private. An adult releases and checks one checkpoint at a time. Use pencils and a supervised table space.',stages:Array.from({length:5},(_,index)=>{const mechanic=index<3?primary:support[index-3] || primary;return {number:index+1,title:titles[index],mechanic,...(spec.packContractVersion===1?{scene:`At the paper station ${index+1}`} : {}),task:descriptions[mechanic],teamwork:'Take turns reading the evidence; another player checks the result.',connection:index===4?'The collected results complete the team mission.':'The checked result identifies the record needed at the next checkpoint.'};})};
}
